WITH v AS (INSERT INTO project_plan_versions (project_id, id) VALUES ($1, 'v-probe-9990') RETURNING id), m AS (INSERT INTO project_plan_milestones (project_id, id, version_id, ord, title) SELECT $1, 'M9990', v.id, 9990, 'проба самотеста' FROM v RETURNING id), t AS (INSERT INTO project_plan_tasks (project_id, id, milestone_id, ord, title, size, state, kind) SELECT $1, 'M9990-T1', m.id, 1, 'проба самотеста', 'S', 'closed', 'dev' FROM m RETURNING id), d AS (INSERT INTO project_documents (project_id, content, content_hash, bytes, revision, updated_at, updated_by, entity_kind, entity_name) VALUES ($1, E'# M9990 · проба самотеста — выжимка этапа\n\n| | |\n|---|---|\n| задач | 2 из 2 закрыты |\n', 'probe-selftest', 90, 1, (extract(epoch from now()) * 1000)::bigint, 'probe-selftest', 'run', 'M9990'), ($1, E'# M9990-T1 · проба самотеста\n', 'probe-selftest', 30, 1, (extract(epoch from now()) * 1000)::bigint, 'probe-selftest', 'run', 'M9990-T1') RETURNING entity_name) INSERT INTO project_runs_log (project_id, id, title, milestone, is_milestone, entity_kind, entity_name) SELECT $1, d.entity_name, d.entity_name || ' · проба самотеста', 'M9990', d.entity_name = 'M9990', 'run', d.entity_name FROM d
